-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.review_undo (
  log_id bigint not null,
  user_id uuid default auth.uid() not null,
  action_id uuid not null,
  state_before jsonb,
  created_at timestamp with time zone default now() not null,
  constraint review_undo_pkey PRIMARY KEY (log_id),
  constraint review_undo_log_id_fkey FOREIGN KEY (log_id) REFERENCES public.review_log(id) ON DELETE CASCADE,
  constraint review_undo_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE
);

CREATE INDEX review_undo_user ON public.review_undo USING btree (user_id, log_id DESC);

alter table public.review_undo enable row level security;

create policy "delete own undo" on public.review_undo
  as permissive
  for delete
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "insert own undo" on public.review_undo
  as permissive
  for insert
  to authenticated
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user) AND (EXISTS ( SELECT 1
   FROM public.review_log l
  WHERE ((l.id = review_undo.log_id) AND (l.user_id = ( SELECT auth.uid() AS uid)))))));

create policy "own undo" on public.review_undo
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.review_undo to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.review_undo to service_role;
